def mc(prompt, options, answer, whys, steps, concept, skill, hint, feedback="", diagram="", diagram_alt=""):
    """Local shortcut: options is a list of 4 strings, answer the 0-based index of the right one,
    whys a dict {wrong index: why}, steps a list of explanation sentences."""
    choices = [C(t, correct=(i == answer), why=("" if i == answer else whys[i])) for i, t in enumerate(options)]
    return MC(prompt, choices, [S("Step " + str(n + 1), text=t) for n, t in enumerate(steps)],
              concept=concept, skill=skill, hint=hint, feedback=feedback, diagram=diagram, diagram_alt=diagram_alt)


def num(prompt, answer, steps, concept, skill, hint, feedback=""):
    return NUM(prompt, answer, [S("Step " + str(n + 1), text=t) for n, t in enumerate(steps)],
               concept=concept, skill=skill, hint=hint, feedback=feedback)


